const rotateAngle = 45;

const directionsConfig = {
  x: [
    [[0, 1, 7, 8], 1],
    [[3, 4, 5], -1],
  ],
  y: [
    [[5, 6, 7], -1],
    [[1, 2, 3], 1],
  ],
} as const;

const getDirection = (key: keyof typeof directionsConfig, value: number) => {
  const condition = directionsConfig[key];
  //@ts-ignore
  const found = condition.find(([list]) => list.includes(value));

  return found ? found[1] : 0;
};

export const moveShadow = (angle: number) => {
  angle = ((angle % 360) + 360) % 360;
  const coordinates = { x: 0, y: 0 };

  const percent = angle * 100 / 90

  //  45*100/45

  // const direction = Math.floor(angle / rotateAngle + 0.5);
  // console.log("🚀", angle.toFixed(0), direction);

  // coordinates.x = getDirection("x", direction);
  // coordinates.y = getDirection("y", direction);

  console.log(percent);
  return coordinates;
};
